const a={login:async(t,o)=>{const e=await fetch("/api/v1/auth/login",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:t,password:o})});if(!e.ok)throw new Error("Invalid credentials");return e.json()},checkSetup:async()=>{const t=await fetch("/api/v1/auth/setup");return t.ok?t.json():{needs_setup:!1}},createAdmin:async(t,o)=>{const e=await fetch("/api/v1/auth/setup",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({username:t,password:o})});if(!e.ok){const n=await e.json().catch(()=>null);throw new Error((n==null?void 0:n.error)||"Setup failed")}return e.json()},logout:()=>{localStorage.removeItem("obs_token"),window.location.href="/login"},isAuthenticated:()=>!!localStorage.getItem("obs_token")};export{a};
